{
  "probability": 0.81,
  "range_low": 0.73,
  "range_high": 0.89,
  "summary": [
    "Historical baseline: 2/3 majorities occurred in 4 of 9 post-1990 elections, anchoring a non-negligible prior for a constitutional majority.",
    "Opposition unity behind Tisza increases the odds of a large bloc forming that could reach a 2/3 majority.",
    "Prediction-market sentiment and currency-market implications suggest upside for the opposition under certain scenarios, though divergence remains.",
    "Incumbency advantages and electoral-system amplification for Fidesz keep the outcome uncertain and restrain the upside potential.",
    "Turnout dynamics and vote fragmentation risk add noise, preventing a guaranteed 2/3 outcome despite favorable signals."
  ],
  "confidence": "high",
  "narrative": "Anchoring on Hungary’s history of 2/3 majorities and integrating current signals, the estimate leans toward a credible chance of a supermajority but remains uncertain. The opposition’s consolidation behind Tisza and market signals push the odds up, while incumbency advantages and turnout volatility cap certainty. Calibrated posterior: 81% with an approximate 0.73–0.89 uncertainty range.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Historical frequency of two-thirds majorities under post-1990 Hungary (4 out of 9 elections), used to anchor the reference class and baseline probability."
    },
    "factor_updates": [
      {
        "factor": "Opposition unity behind Tisza",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Consolidation behind a single opposition banner reduces vote-splitting and increases the chance of a large bloc achieving a 2/3 majority (supportive media coverage and FT reporting)."
      },
      {
        "factor": "Prediction-market sentiment toward Tisza",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Some prediction-market instruments and polls tilt toward Tisza, signaling higher odds of a substantial opposition share, though results are not uniform."
      },
      {
        "factor": "Incumbency and electoral-system advantages for Fidesz",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Historical amplification for Fidesz under the current system suggests a structural barrier to a guaranteed 2/3, even with broad support."
      },
      {
        "factor": "Economic/currency market signals about regime change",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Markets pricing in potential regime change if the opposition wins raises perceived upside for a large bloc but also reflects uncertainty."
      },
      {
        "factor": "Poll divergence and turnout uncertainty",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Divergent polls and turnout dynamics introduce ambiguity, tempering confidence in a decisive 2/3 outcome."
      }
    ],
    "synthesis_rationale": "Starting from a 0.44 anchor based on historical frequency, I applied moderate positive deltas from opposition unity, market sentiment, and perceived regime-change implications, while accounting for incumbent advantages and turnout/poll uncertainties. The result is a calibrated posterior of 0.81 with a plausibly wide but bounded uncertainty range (0.73–0.89) to reflect model fragility and electoral-system idiosyncrasies."
  }
}

{
  "probability": 0.81,
  "range_low": 0.72,
  "range_high": 0.90,
  "summary": [
    "Bayesian posterior for a supermajority in 2026 Hungary is 81%, reflecting calibration against the historical base rate.",
    "Key updates: opposition unity behind Tisza, predictive-market signals showing upside for Tisza, and enduring incumbency/system advantages that could still help Fidesz.",
    "Poll divergence and turnout uncertainty temper confidence, keeping outcomes highly contingent on district-level results and mobilization."
  ],
  "confidence": "high",
  "narrative": "Starting from a long-run base rate of ~44% for a 2/3 majority in Hungary's current system, multiple recent factors pull the probability toward a high-80s posterior. The strongest drivers are opposition unity behind Tisza and market signals suggesting potential regime change, but structural biases and turnout uncertainty keep the range wide around the central estimate.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Historical base-rate: 2/3 majorities occurred in 4 of 9 post-1990 elections under Hungary's current system, giving a starting anchor near 0.44."
    },
    "factor_updates": [
      {
        "factor": "Opposition unity behind Tisza",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "FT reports opposition groups uniting behind Tisza and some polls showing Tisza leading, increasing the odds that a large bloc could emerge."
      },
      {
        "factor": "Prediction-market sentiment toward Tisza",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Divergent polls and some markets reflect upside for Tisza, signaling a credible path to a 2/3 majority for the opposition in certain scenarios."
      },
      {
        "factor": "Incumbency and electoral-system advantages for Fidesz",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Historical wins under the current system show Fidesz can still convert broad support into a near-2/3 outcome, providing a downside anchor."
      },
      {
        "factor": "Economic/currency market signals about regime change",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Market commentary suggests a potential regime change is priced in if the opposition wins, which reinforces the upside case for a 2/3 outcome under certain market scenarios."
      },
      {
        "factor": "Poll divergence and uncertainty",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Mixed polls across firms create uncertainty, preventing a single-direction move and supporting a wide potential range."
      },
      {
        "factor": "Historical base-rate for 2/3 outcomes",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Past frequency of 2/3 outcomes offers a modest baseline, but current dynamics can push probabilities above or below this mark."
      }
    ],
    "synthesis_rationale": "Starting from the anchor 0.44, multiple moderate upward updates from opposition unity, market sentiment, and incumbency effects were integrated, with weak neutral factors and historical precedent providing calibration. The resulting posterior of 0.81 reflects a calibrated consolidation of evidence, while acknowledging substantial uncertainty due to polling divergence and turnout effects. The range accommodates plausible variation given district-level sensitivity and potential fragmentation."
  }
}

{
  "probability": 0.52,
  "range_low": 0.38,
  "range_high": 0.60,
  "summary": [
    "Opposition unity behind Tisza increases the odds that a non-Fidesz bloc could reach a 2/3 majority.",
    "Prediction-market signals and credible polls show divergent outcomes, suggesting upside risk to a large bloc but with substantial uncertainty.",
    "Incumbency advantages and the electoral-system amplification for Fidesz temper the likelihood of a 2/3 win, keeping probability near the historical baseline.",
    "Turnout dynamics and the risk of vote fragmentation introduce further uncertainty, preventing a strong confidence in any single outcome."
  ],
  "confidence": "medium",
  "narrative": "Starting from a historical baseline around 0.44 for a 2/3 majority, the opposition’s consolidation behind Tisza and market/poll signals push the odds modestly higher, but incumbent advantages and fragmentation risk cap the rise. The result is a measured tilt toward a possible 2/3 outcome, yet with substantial uncertainty due to turnout and district-level dynamics.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Historical reference: in post-1990 Hungary, 2/3 majorities occurred in 4 of 9 elections (approx. 44%), establishing a baseline probability for any party/coalition achieving a supermajority."
    },
    "factor_updates": [
      {
        "factor": "Opposition unity behind Tisza",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "FT reports opposition groups uniting behind Tisza and some polls showing Tisza leading, which raises the odds that a large opposition bloc could reach or approach a two-thirds majority."
      },
      {
        "factor": "Prediction-market sentiment toward Tisza",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Diversified polls and markets implying upside for a large bloc suggest the potential for a 2/3 outcome, adding weight to an above-baseline probability."
      },
      {
        "factor": "Incumbency and electoral-system advantages for Fidesz",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Past electoral-system amplification benefits Fidesz; even with opposition gains, structural biases can limit the translation of broad support into a 2/3 victory for any bloc."
      },
      {
        "factor": "Turnout dynamics and mobilization of inactive voters",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Mobilization of previously inactive voters could tilt results in favor of whichever bloc consolidates support, increasing the chance of a large bloc achieving 2/3."
      },
      {
        "factor": "Third-party fragmentation risk (e.g., Our Homeland Movement)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Additional parties can dilute a bloc’s vote share and hinder reaching a 2/3 majority, reducing the odds of a clear constitutional majority for any single bloc."
      }
    ],
    "synthesis_rationale": "Starting from a 0.44 anchor, the updates tilt toward higher odds of a large bloc (notably the opposition) achieving 2/3 due to unity and turnout potential, while countervailing forces (incumbency advantages, fragmentation risk) dampen that rise. The synthesis yields a modest above-baseline probability with a broad uncertainty range, hence the 0.52 central estimate and 0.38–0.60 range, reflecting calibration for political-outcome uncertainty and potential turnout/distribution effects."
  }
}
